let pro_err={
    // lastTick:-1,
    errList:[],
    print:0,
    catchError (func,message){
        try{
            return func()
        }catch (e) {
            // if(Game.time!=pro_err.lastTick)pro_err.errList = []
            // if(Game.creeps[message])Game.creeps[message].suicide()
            let data = e.stack
            if(message)data = "\n"+message+"\n"+e.stack
            pro_err.errList.push(data+"\n\n**************\n")
        }
    },
    throwAllError () {
        if(pro_err.errList.length){
            let tmp = pro_err.errList;
            pro_err.errList = [];
            if(!tmp.length){
                pro_err.print=0;
            }
            if(pro_err.print){
                pro_err.print+=1;
                if(pro_err.print>10)pro_err.print=0;
                console.log(tmp);
            }
            else{
                pro_err.print+=1;
                throw new Error(tmp);
            }
        }
    },
}

global.HelperError=pro_err

modules.class_RoomArray:
let RoomArray_proto= {
    exec(x,y,val){
        let tmp = this.arr[x*50+y]
        this.set(x,y,val);
        return tmp
    },
    get(x,y){
        return this.arr[x*50+y];
    },
    set(x,y,value){
        this.arr[x*50+y]=value;
    },
    init(){
        if(!this.arr)
            this.arr = new Array(50*50)
        for(let i=0;i<2500;i++){
            this.arr[i]=0;
        }
        return this;
    },
    forEach(func){
        for(let y = 0; y < 50; y++) {
            for(let x = 0; x < 50; x++) {
                func(x,y,this.get(x,y))
            }
        }
    },
    for4Direction(func,x,y,range=1){
        for(let e of [[1,0],[-1,0],[0,1],[0,-1]]){
            let xt=x+e[0]
            let yt=y+e[1]
            if(xt>=0&&yt>=0&&xt<=49&&yt<=49)
                func(xt,yt,this.get(xt,yt))
        }
    },
    forNear(func,x,y,range=1){
        for(let i=-range;i<=range;i++){
            for(let j=-range;j<=range;j++){
                let xt=x+i
                let yt=y+j
                if((i||j)&&xt>=0&&yt>=0&&xt<=49&&yt<=49)
                    func(xt,yt,this.get(xt,yt))
            }
        }
    },
    forBorder(func,range=1){
        for(let y = 0; y < 50; y++) {
            func(0,y,this.get(0,y))
            func(49,y,this.get(49,y))
        }
        for(let x = 1; x < 49; x++) {
            func(x,0,this.get(x,0))
            func(x,49,this.get(x,49))
        }
    },
    initRoomTerrainWalkAble(roomName){
        let terrain = new Room.Terrain(roomName);
        this.forEach((x,y)=> this.set(x,y, terrain.get(x,y)==1?0:terrain.get(x,y)==0?1:2))
    }
}
class RoomArray {
    constructor(){
        this.__proto__ = RoomArray_proto
    }
}


global.RoomArray = RoomArray;

