            if (cap) {
                let res = cap.store.getLessResTypes().head()
                pc.withdraw(cap, res, Math.min(cap.store[res], pc.store.getFreeCapacity(res)))
                if (pc.store.isFull()) {
                    let res = pc.store.getLessResTypes().head()
