                if(vis[i+"_"+j])continue;
                let jj = labChangeDirection?j:1-j;
                let structs = labs[i+1].charAt(j+1)
                if(structs == '☢')
                    structMap["lab"].push([labX+i,labY+jj])
                else
                    structMap["road"].push([labX+i,labY+jj])
            }
        }

