modules.strategy_highLevel:
/**
 * 在有 storage使用的策略
 */
let pro = {
    workerManager(room) {
        let spawnWorker = () => {
            let body = StationWork.getMiddleLevelWorkerBodyConfig(room);
            let partCnt = body.filter(e => e == WORK).length;
            let boostLevel = StationLab.boostAbleLevel(room, "build", partCnt, 1)
            let isBoost = room.creeps("carrier").length && boostLevel >= 0;
            if (LOCAL_SHARD_NAME == "6g3y-station") isBoost = false
            let task = []
            if (isBoost) task = StationLab.generatorBoostLevelTask(room, "build", partCnt, boostLevel)
            StationHive.trySpawn(room, room.name, body, "worker", task)
        }
        let spawnHighLevelWorker = () => {
            let body = StationWork.getHighLevelWorkerBodyConfig(room);
            let boostRes = { [BOOST_RES["build"][1]]: 30 * 30, [BOOST_RES["fatigue"][1]]: 10 * 30, [BOOST_RES["capacity"][1]]: 10 * 30 }
            if (body.filter(e => e == WORK).length != 30 || !StationLab.boostAble(room, boostRes) || room.creeps("carrier").length == 0)
                return spawnWorker();

            let task = StationLab.generatorBoostResTask(boostRes, room)
            StationHive.trySpawn(room, room.name, body, "worker", task)
        }
        // log((room.storage.store[RESOURCE_ENERGY]-100000)/50000)
        let EnergyOver = (room.storage.store[RESOURCE_ENERGY] - 250000) / 50000 > room.creeps("worker", false).length //能量溢出，可以多生爬来修
        let noWorker = room.creeps("worker", false).length < 1;

        if (room.creeps("worker", false).length + room.creeps("carrier", false).length == 0) {// 或者爬都死光了
            spawnWorker();
        } else if (room.constructionSite.length) {//如果有工地也必生
            if (noWorker || (EnergyOver && !isSaveCpu)) // 如果一个都没有就生一个（保证有人去修工地,如果能量够可以多生几个
                spawnWorker();
            // add by an_w
            let num = room.constructionSite.length;
            if (room.creeps("worker", false).length < 3 && num >= 3 && room.level == 8) {// 如果一个都没有就生一个（保证有人去修工地,如果能量够可以多生几个
                spawnWorker();
            }
        } else if (StationDefense.needBuildWall(room) && !MIN_CPU) {//如果需要修墙
            if (room.level < 8 && (noWorker || EnergyOver)) { // 8前 级优先修墙 如果一个都没有就生一个（保证有人去修工地,如果能量够可以多生几个
                spawnWorker();
            } else if (((room.storage.store[RESOURCE_ENERGY] > 180000) && noWorker) || EnergyOver) {
                if (isSaveCpu) spawnHighLevelWorker();
                else spawnWorker();
                // spawnWorker();
            }
        } else if ((room.storage.store[RESOURCE_ENERGY] - 350000) / 50000 > room.creeps("worker", false).length && room.controller.level == 8 && StationDefense.needBuildWall(room) && !MIN_CPU && !isSaveCpu) { //如果能量还是太多了，就拼命修墙
            spawnWorker();
        }

        let minWorkerCnt = 0;
        let upgradeFlag = room.flags("repair").head();
        if (upgradeFlag && room.terminal && room.terminal.my) {
            let split = upgradeFlag.getNameSplit();
            if (split.length >= 2) minWorkerCnt = parseInt(split[2])
        }
        if (room.creeps("worker", false).length < minWorkerCnt) {
            spawnWorker();
        }

        // }else if(room.level==8&&(needRepairWalls||room.constructionSite.length)){
        //
        //     if(room.creeps("worker",false).length<1||room.constructionSite.length&&(room.storage.store[RESOURCE_ENERGY]-100000)/50000>room.creeps("worker",false).length) //如果有工地且能量够的情况
        //         spawnWorker();
        // }
        // if((room.constructionSite.length||needRepairWalls||room.creeps("worker",false).length+room.creeps("carrier",false).length==0)  // 有工地的时候在造worker 或者全死光了
        //     &&(room.creeps("worker",false).length<1||(room.storage.store[RESOURCE_ENERGY]-100000)/50000>room.creeps("worker",false).length)){
        //     spawnWorker();
        // }

        if (room.storage.store[RESOURCE_ENERGY] < 3000) {
            _.values(room.memory[StationSources.stationName]).filter(e => Game.getObjectById(e.id).energy).forEach(data => {
                if (data["creeps"].filter(e => Game.getObjectById(e)).length == 0 && room.creeps().filter(e => e.memory.role == "harvestEnergyKeeper").length == 0) {
                    let posLen = room[data["id"]].pos.nearPos(1).filter(e => e.walkable()).length
                    let targetCnt = posLen * 1.5 - room.creeps("worker").filter(e => e.headTask() && e.headTask().id == data["id"]).length;
                    if (Math.min(6, Math.ceil(targetCnt)) > 0) {
                        let creep = room.creeps("worker").filter(e => e.storeEmpty() && e.isFree()).head()
                        if (creep) creep.addTask(StationSources.generatorReleaseAbleHarTask(data))
                    }
                }
            });
        }
    },
    unboostWorker(room, creep) {
        if (creep.memory.needUnboost === undefined) creep.memory.needUnboost = creep.body.filter(e => e.boost).length;
        if (creep.memory.needUnboost) {
            let tasks = StationLab.generatorUnboostTask(room);
            if (tasks.length) {
                creep.addTask(tasks);
            }
        }
    },
    workerManagerAfterCarrier(room) {
        // worker 核心工作
        let isCarryFree = room.creeps("carrier").filter(e => e.isFree()).length
        let StorageCarryEnergyTasks = StationCarry.generatorCarryStorageEnergyTask(room);
        let lowEnergyCarry = !room.creeps("carrier").length && StationSources.generatorCarryEnergyTask(room, StationHive.HiveNeedToFill(room) ? 1200 : 500)
        room.creeps("worker").filter(e => e.memory.tasks.length <= 1).forEach(creep => { // 优先 unboost 回收t2
            if (creep.ticksToLive < 80 && creep.memory.needUnboost === undefined)
                pro.unboostWorker(room, creep)
        })
        room.creeps("worker").filter(e => e.isFree()).forEach(creep => {
            if (creep.storeEmpty()) {
                if (creep.ticksToLive < 80 && creep.memory.needUnboost === undefined) {
                    pro.unboostWorker(room, creep)
                } else if (StorageCarryEnergyTasks.length > 0) {
                    creep.addTask(StorageCarryEnergyTasks)
                } else if (lowEnergyCarry && lowEnergyCarry.length) {
                    creep.addTask(lowEnergyCarry.pop())
                }
            } else {
                if (room.creeps("carrier", false).length == 0 && !isCarryFree && StationHive.HiveNeedToFill(room)) {
                    creep.addTask(StationHive.generatorFillHiveTask(room, creep));
                } else if (StationWork.constructionNeedBuild(creep.mainRoom()) && !room.isDownGrade()) {
                    creep.addTask(StationWork.generatorBuildTask(creep))
                } else if (StationDefense.needBuildWallWorkerFree(room) && !room.isDownGrade()) {
                    creep.addTask(StationDefense.generatorRepairTask(room))
                }
                else if (!StationDefense.needBuildWallWorkerFree(room) && room.level < 8) {
                    creep.addTask(StationUpgrade.generatorUpgradeTask(room));
                }
            }
        })
    },
    carrierOperatorBoost(room) {
        //boost lab 操作
        let freeCarries = room.creeps("carrier").filter(e => e.isFree() && e.ticksToLive > 50 && e.store.getUsedCapacity() == 0);
        let task = StationLab.generatorOperatorBoostTask(room);
        if (task.length && freeCarries.length) freeCarries.pop().addTask(task);
        if (!freeCarries.length) return;

        // 填充lab能量
        task = StationLab.generatorFillEnergyTask(room)
        if (task.length && freeCarries.length) freeCarries.pop().addTask(task);
        if (!freeCarries.length) return;

        // lab 反应
        task = StationLab.generatorClearLabRes(room);
        if (task.length == 0) task = StationLab.generatorFillReactionTask(room);
        if (freeCarries.length && task.length) freeCarries.pop().addTask(task);
        if (!freeCarries.length) return;

    },
    carrierManager(room) {
        pro.carrierOperatorBoost(room);

        let freeCarries = room.creeps("carrier").filter(e => e.isFree() && e.storeEmpty());

        let carryLinkTasks = StationSources.generatorCarryEnergyFromLinkTask(room); // 优先整理中央link的资源，这个最快
        if (carryLinkTasks.length && freeCarries.length) freeCarries.pop().addTask(carryLinkTasks)

        let FillPowerSpawnTasks = StationCarry.generatorFillPowerSpawnTask(room); // 保证烧power的速度
        // if(FillPowerSpawnTasks.length&&freeCarries.length)freeCarries.pop().addTask(FillPowerSpawnTasks)
        if (FillPowerSpawnTasks.length && freeCarries.length)
            freeCarries.pop().addTask(UtilsTask.task(room.powerSpawn, "fillPowerSpawnContinuous", "registerUsed"))

        /**
         * 优先填tower 和 ext
         * 如果填完后还有能量就放回storage
         */
        let fillTowerTasks = StationTower.generatorFillEnergyTasks(room)
        let StorageCarryEnergyTasks = StationCarry.generatorCarryStorageEnergyTask(room);

        if (StorageCarryEnergyTasks.length) {
            room.creeps("carrier").filter(e => e.isFree() && !e.storeContainsEnergyOtherResType()).forEach(creep => {
                if (StationHive.HiveNeedToFill(room)) {
                    creep.addTask(StationHive.generatorFillHiveTask(room, creep));
                    if (creep.storeEmpty()) creep.addTask(StorageCarryEnergyTasks);
                } else if (fillTowerTasks.length) {
                    creep.addTask(fillTowerTasks.shift())
                    if (creep.storeEmpty()) creep.addTask(StorageCarryEnergyTasks);
                }
            })
        }
        room.creeps("carrier").filter(e => !e.storeEmpty() && e.isFree()).forEach(e => e.fillAllMainRoomStorage())

        // container 能量
        freeCarries = room.creeps("carrier").filter(e => e.isFree() && e.ticksToLive > 50); // 从这里开始下面的任务最好大于150ttl
        if (room.creeps("harvestEnergyKeeper").length && room.link.length < 6 || room.level < 8) {// 必须要有挖矿的 和 6个 link才会不去搬运能量
            carryLinkTasks = StationSources.generatorCarryEnergyTask(room);
            carryLinkTasks.forEach(e => {
                if (freeCarries.length) { freeCarries.pop().addTask(e); }
            })
        }

        // 捡起任务 9tick更新一次，比较耗时 缓存起来
        let pickTasks = pro.pickTasksMap[room.name] || []
        if ((Game.time + room.hashCode()) % 9 == 0) {
            onlyEnergy = false
            if (room.storage.store.getFreeCapacity() < 5000 && !room.terminal) {
                onlyEnergy = true
            }
            pickTasks = StationCarry.generatorPickTask(room, onlyEnergy).concat(StationMineral.generatorCarryMineralTask(room))
        }
        if (freeCarries.length && pickTasks.length) { freeCarries.pop().addTask(pickTasks.shift()); }
        pro.pickTasksMap[room.name] = pickTasks;


        if (StorageCarryEnergyTasks.length) {
            if (!freeCarries.length) return;

            // 分配升级的运送
            let task = StationUpgrade.generatorFillEnergyTask(room.name, freeCarries.head().getPartCnt(CARRY) * 50);
            if (freeCarries.length && task.length)
                freeCarries.pop().addTask(task);
            if (!freeCarries.length) return;

            //填权力巢
            if (freeCarries.length && task.length)
                freeCarries.pop().addTask(task);
            if (!freeCarries.length) return;

            //填核弹人
            task = StationCarry.generatorFillNukerTask(room);
            if (freeCarries.length && task.length)
                freeCarries.pop().addTask(task);
            if (!freeCarries.length) return;

            //填factory
            task = StationFactory.generatorFillTask(room);
            if (freeCarries.length && task.length)
                freeCarries.pop().addTask(task);
            if (!freeCarries.length) return;

            // let con = Game.getObjectById("6669490889bcac4cecd9c259")
            // resType = con.store.getResTypeList()[1]
            // if (resType) {
            //     let ops = { resType: resType, resCount: con.store.getUsedCapacity(resType) }
            //     task = [UtilsTask.task(con, "carryRes", "registerUsed", ops)]
            // }
            // if (freeCarries.length && task.length)
            //     freeCarries.pop().addTask(task);
            // if (!freeCarries.length) return;

            //填Terminal
            // task = StationCarry.generatorFillTerminalTask(room);
            // if (freeCarries.length && task.length)
            //     freeCarries.pop().addTask(task);
            // if (!freeCarries.length) return;

        }


    },
    pickTasksMap: {},
    trySpawnCarrier(room) { // 分配creep个数，最多7个，
        room.memory.carryBusy = room.memory.carryBusy || []
        if (!room.memory.carryBusy.length) room.memory.carryBusy = []
        let avgBusy = room.memory.carryBusy.sum() / room.memory.carryBusy.length
        // log(avgBusy,room.creeps("carrier",false).length,room.creeps("carrier",false).length*0.85)

        if ((room.creeps("carrier", false).length <= 0 && (room.storage[RESOURCE_ENERGY] > 3000 || room.creeps("harvestEnergyKeeper", false).length > 0)) || (
            room.creeps("carrier", false).length <= 7 &&
            avgBusy > room.creeps("carrier", false).filter(e => !e.ticksToLive || e.ticksToLive > e.body.length * 3).length * 0.85)) {
            StationHive.trySpawn(room, room.name, StationCarry.getCarrierBodyConfig(room), "carrier", [])
        }
        if (room.memory.carryBusy.length > 130) room.memory.carryBusy = room.memory.carryBusy.slice(-100)
        room.memory.carryBusy.push(room.creeps("carrier").filter(e => !e.isFree()).reduce((a) => a + 1, 0))
    },
    processPowerSpawn(room) {
        if (room.powerSpawn) {
            if (room.powerSpawn.store[RESOURCE_ENERGY] >= 50 && room.powerSpawn.store[RESOURCE_POWER] >= 1) {
                room.powerSpawn.processPower()
            }
        }
    },
    exec(room) {
        if (!MIN_CPU) pro.processPowerSpawn(room)// 每tick都要处理
        if ((Game.time + room.hashCode()) % 3 != 0) return;
        if (MIN_CPU && (Game.time + room.hashCode()) % 2) return;
        ManagerAutoPlanner.tryAutoBuildHighLevel(room);



        StationCarry.transformLink(room);
        // worker 优先 carrier 的事件
        pro.workerManager(room); // 包括了生爬逻辑
        pro.carrierManager(room);
        // 等搬运工搬运剩下的才让worker帮忙
        pro.workerManagerAfterCarrier(room);



        pro.trySpawnCarrier(room); // 一定要在carrierManager后面
        StationSources.trySpawnHarKeeper(room);
        StationMineral.trySpawnHarKeeper(room);
        StationUpgrade.spawnUpgrader(room);


        //最后回收全部资源！
        // room.creeps("carrier").filter(e=>!e.storeEmpty()&&e.isFree()).forEach(e=>{
        //     e.fillAll(room.storage)
        // })


    }
}



global.StrategyHighLevel = pro;

modules.strategy_lowLevel:
/**
 * 在没有 storage使用的策略
 */


Creep.prototype.lowLevelDefense = function () {
    let em = this.pos.findClosestByPath(FIND_HOSTILE_CREEPS);
    if (em) {
        this.attack(em)
        this.moveTo(em)
        return;
    }
    this.memory.dontPullMe = false;
}

let pro = {
    pickTasksMap: {},
    tryCreateCons(pos, struct) {
        let head = pos.lookFor(LOOK_STRUCTURES).filter(e => e.structureType == struct).head()
        if (!head) pos.createConstructionSite(struct)
    },
    trySpawnLowLevelDefense(room) {
        let totalEnergy = room.getEnergyCapacityAvailable(room);
        let attackNeed = BODYPART_COST[ATTACK] + 3 * BODYPART_COST[MOVE]
        let cnt = Math.floor(totalEnergy / attackNeed)
        let body = ManagerCreeps.calcBodyPart({ [MOVE]: cnt * 3, [ATTACK]: cnt })
        StationHive.trySpawn(room, room.name, body, "lowLevelDefense", [UtilsTask.taskData("lowLevelDefense")])
    },
    pickTasks(room, freeCarries, onlyEnergy = false) {
        // 捡起任务 9tick更新一次，比较耗时 缓存起来
        let pickTasks = pro.pickTasksMap[room.name] || []
        if ((Game.time + room.hashCode()) % 9 == 0) {
            pickTasks = StationCarry.generatorPickTask(room, onlyEnergy).concat(StationMineral.generatorCarryMineralTask(room))
        }
        if (freeCarries.length && pickTasks.length) { freeCarries.pop().addTask(pickTasks.shift()); }
        pro.pickTasksMap[room.name] = pickTasks;
    },
    exec(room) {
        if ((Game.time + room.hashCode()) % 3 != 0) {
            return
        }
        if (room.spawn.length && room.find(FIND_HOSTILE_CREEPS).filter(e => e.body.filter(e => e != MOVE).length).length) {// 如果有敌人的爬且不是侦察兵
            if (room.creeps("lowLevelDefense").length < 3 && room.tower.length == 0) pro.trySpawnLowLevelDefense(room)
        }
        // if ((room.getEnergyCapacityAvailable(room) < 800 || (room.storage && !room.storage.my))) {
        if ((room.getEnergyCapacityAvailable(room) < 800 )) {
            ManagerAutoPlanner.tryAutoBuildLowLevel0(room);
            // if((Game.time+room.hashCode()) % 150 == 0  && Game.cpu.bucket>50 && room.memory.structMap){
            //     room.memory.structMap[STRUCTURE_SPAWN].take(1).forEach(e=>{pro.tryCreateCons(new RoomPosition(e[0],e[1],room.name),STRUCTURE_SPAWN)})
            //     room.memory.structMap[STRUCTURE_EXTENSION].take(10).forEach(e=>{pro.tryCreateCons(new RoomPosition(e[0],e[1],room.name),STRUCTURE_EXTENSION)})
            // }
            let creeps = room.creeps("worker").filter(e => e.storeEmpty() && e.isFree())
            pro.pickTasks(room, creeps, true)

            /** 利用 和 生成 新的 worker*/
            _.values(room.memory[StationSources.stationName]).filter(e => Game.getObjectById(e.id).energy)
                .sort((a, b) => Game.getObjectById(b.id) ? Game.getObjectById(b.id).energy - Game.getObjectById(a.id).energy : 0) // 如果有视野 按能量多少从大到小排序
                .forEach(data => {
                    // room[data["id"]].pos.findInRange(FIND_STRUCTURES,1).filter(e=>e.structureType = STRUCTURE_WALL).length;
                    let posLen = room[data["id"]].pos.nearPos(1).filter(e => e.walkable()).length
                    let targetCnt = posLen * 1.5 - room.creeps("worker").filter(e => e.headTask() && e.headTask().id == data["id"]).length;
                    if (Math.min(6, Math.ceil(targetCnt)) > 0) {
                        let creep = room.creeps("worker").filter(e => e.storeEmpty() && e.isFree()).head()
                        // log(StationWork.getLowLevelWorkerBodyConfig(spawnRoom,false))
                        if (creep) creep.addTask(StationSources.generatorReleaseAbleHarTask(data))
                        else if (room.creeps("worker").length < 20 && !room.find(FIND_FLAGS).filter(e => e.getPrefix() == "claimCrossShard").length) {
                            let spawnRoom = StationHive.getClosestSpawnRoom(room, 7, 3, 15)
                            if (!spawnRoom) {
                                return;
                            }
                            if (spawnRoom.name != room.name && room.creeps("worker", false).length >= 4) return;// 如果不是自己的房间最多生4个
                            StationHive.trySpawn(spawnRoom, room.name, StationWork.getLowLevelWorkerBodyConfig(spawnRoom), "worker", [])
                        }
                    }
                });

            creeps = room.creeps("worker").filter(e => e.storeEmpty() && e.isFree())
            if (creeps.length) {
                if (StationCarry.roomMassStoreCnt(room, RESOURCE_ENERGY) > 2000) {
                    creeps.pop().addTask(StationCarry.generatorCarryStorageEnergyTask(room));
                }
            }

            room.creeps("worker").filter(e => !e.storeEmpty() && e.isFree()).forEach(creep => {
                if (StationHive.HiveNeedToFill(room)) {
                    creep.addTask(StationHive.generatorFillHiveTask(room, creep));
                } else if (room.level > 1 && StationWork.constructionNeedBuild(creep.mainRoom()) && !room.isDownGrade()) {
                    creep.addTask(StationWork.generatorBuildTask(creep))
                }
                else {
                    creep.addTask(StationUpgrade.generatorUpgradeTask(room));
                }
            })
        } else { // 3级的时候可以分化creep来了
            ManagerAutoPlanner.tryAutoBuildLowLevel800(room);

            if (room.creeps("worker", false).length + room.creeps("carrier", false).length == 0)// 如果没用搬运的就直接优先生一个
                StationHive.trySpawn(room, room.name, StationWork.getMiddleLevelWorkerBodyConfig(room), "worker", [])

            StationSources.trySpawnHarKeeper(room);


            let creeps = room.creeps("worker").filter(e => e.storeEmpty() && e.isFree())
            if (creeps.length) {
                if (StationCarry.roomMassStoreCnt(room, RESOURCE_ENERGY) > 2000) {
                    creeps.pop().addTask(StationCarry.generatorCarryStorageEnergyTask(room));
                }
            }

            // 挖矿
            _.values(room.memory[StationSources.stationName]).forEach(data => {
                if (data["creeps"].length == 0) {
                    let posLen = room[data["id"]].pos.nearPos(1).filter(e => e.walkable()).length
                    let targetCnt = posLen * 1.5 - room.creeps("worker").filter(e => e.headTask() && e.headTask().id == data["id"]).length;
                    if (Math.min(6, Math.ceil(targetCnt)) > 0) {
                        let creep = room.creeps("worker").filter(e => e.storeEmpty() && e.isFree()).head()
                        if (creep) creep.addTask(StationSources.generatorReleaseAbleHarTask(data))
                    }
                }
            });

            if ((room.constructionSite.length || room.creeps(undefined, false).length == 0)  // 有工地的时候在造worker 或者全死光了
                && (room.creeps("worker", false).length < 2 ||
                    ((room.creeps("carrier").filter(e => e.isFree()).length > room.creeps("worker", false).length)
                        && room.creeps("worker", false).filter(e => e.isFree()).length < 2))) {
                StationHive.trySpawn(room, room.name, StationWork.getMiddleLevelWorkerBodyConfig(room), "worker", [])
            }


            // 生 升级的
            if (Game.getObjectById(room.memory[StationUpgrade.stationName][STRUCTURE_CONTAINER]))
                if (room.creeps("upgrader").length == 0 || room.creeps("upgrader").length < room.creeps("carrier")
                    .filter(e => e.isFree() && e.store[RESOURCE_ENERGY] > 0).length - 1) {
                    StationUpgrade.spawnUpgrader(room)
                }

            // 内矿的能量搬运 和掉落资源
            let pickTasks = StationCarry.generatorPickTask(room, true)
            let carryTasks = StationSources.generatorCarryEnergyTask(room);
            room.creeps("carrier").filter(e => e.storeEmpty() && e.isFree()).forEach(creep => {
                if (carryTasks.length) {
                    creep.addTask(carryTasks.pop())
                } else if (pickTasks.length) {
                    creep.addTask(pickTasks.shift())
                }
            })

            if (!creeps.length) creeps = room.creeps("carrier").filter(e => e.storeEmpty() && e.isFree())
            if (creeps.length) {
                if (StationCarry.roomMassStoreCnt(room, RESOURCE_ENERGY) > 2000) {
                    creeps.pop().addTask(StationCarry.generatorCarryStorageEnergyTask(room));
                }
            }

            // 如果内矿搬不动了生一个
            if (room.creeps("carrier", false).length < 1 || carryTasks.length) {
                StationHive.trySpawn(room, room.name, StationCarry.getCarrierBodyConfig(room), "carrier", [])
            }

            // 剩下的给 worker 搬运
            room.creeps("worker").filter(e => e.storeEmpty() && e.isFree()).forEach(creep => {
                if (carryTasks.length) {
                    creep.addTask(carryTasks.pop())
                }
            })

            // 填充任务
            let fillTowerTasks = StationTower.generatorFillEnergyTasks(room)
            room.creeps("carrier").filter(e => !e.storeEmpty() && e.isFree()).forEach(creep => {
                if (StationHive.HiveNeedToFill(room)) {
                    creep.addTask(StationHive.generatorFillHiveTask(room, creep));
                } else if (fillTowerTasks.length) {
                    creep.addTask(fillTowerTasks.shift())
                }
            })

            // 分配升级的运送
            let creep = room.creeps("carrier").filter(e => !e.storeEmpty() && e.isFree()).head();
            if (creep) {
                let task = StationUpgrade.generatorFillEnergyTask(room.name, creep.getPartCnt(CARRY) * 50);
                if (task.length > 0) {
                    creep.addTask(task);
                }
            }

            let lowEnergyCarry = StationSources.generatorCarryEnergyTask(room, StationHive.HiveNeedToFill(room) ? 1200 : 500)
            room.creeps("worker").filter(e => e.isFree()).forEach(creep => {
                if (creep.storeEmpty()) {
                    if (lowEnergyCarry.length)
                        creep.addTask(lowEnergyCarry.pop())
                } else {
                    if (StationHive.HiveNeedToFill(room)) {
                        creep.addTask(StationHive.generatorFillHiveTask(room, creep));
                    } else if (StationWork.constructionNeedBuild(creep.mainRoom()) && !room.isDownGrade()) {
                        creep.addTask(StationWork.generatorBuildTask(creep))
                    }
                    else {
                        creep.addTask(StationUpgrade.generatorUpgradeTask(room));
                    }
                }
            })
        }
    }
}


global.StrategyLowLevel = pro;

modules.strategy_factoryPowerCreep:
/**
 * powerCreep operator factory strategy
 *
 *
 * 1-5级 的 PC 的管理策略
 * Operator Factory level= OP + F + level
 * creepName = “OPF”+level 例如 OPF1,OPF2
 *
 * _.keys(Game.powerCreeps).sort()
 */

// log(POWER_INFO)
let pro = {
    getPowerCreep(room, flag) {
        if (!flag) flag = ManagerFlags.getFlagsByPrefix("OPF").filter(e => e.pos.roomName == room.name).head()
        if (flag) {
            let pc = Game.powerCreeps[flag.getNameSplit()[1]]
            if (!pc || !pc.ticksToLive || LOCAL_SHARD_NAME != (pc.shard || LOCAL_SHARD_NAME))
                return;
            return pc;
        }
    },
    getPowerFactoryLevel(room, flag) {
        let pc = pro.getPowerCreep(room, flag)
        if (!pc) return undefined
        let power = pc.powers[PWR_OPERATE_FACTORY]
        if (power)
            return power.level
    },
    execRoom(flag) {
        // Game.powerCreeps.OPF1.memory = {role: "OPF",roomName:flag.pos.roomName,tasks:[]}
        let room = flag.room;
        if (!room || !room.my) return console.log(flag.name + ":不是自己的房间")
        if (!room.powerSpawn) return console.log(flag.name + ":没有 PowerSpawn")
        let pc = Game.powerCreeps[flag.getNameSplit()[1]]//pro.getPowerCreep(room,flag);
        if (!pc) return console.log(flag.name + ":没有创建 PowerCreep")
        if (!pc.ticksToLive && (!pc.spawnCooldownTime || pc.spawnCooldownTime > Date.now())) {
            pc.spawnPowerCreep(room.powerSpawn, "OPF", flag.pos.roomName)
        }
        if (!pc.ticksToLive) return;
        if (pc.isFree()) {
            let obj = undefined
            if (pc.needRenewInRoom()) pc.addRenewMainRoomTask();
            else if (pc.needSaveOps()) pc.saveRoomOps();
            else if (pc.needGetOps()) pc.getRoomOps();
            else if (obj = pc.needOpExt()) pc.addTask(UtilsTask.task(obj, "OpExt"))
            else if ((obj = pc.needOpStorage(pc.mainRoom().storage))) pc.addTask(UtilsTask.task(room.storage, "OpStorage"))
            else if (obj = pc.needOpSource()) pc.addTask(UtilsTask.task(obj, "OpSource"))
            else if (pc.powers[PWR_OPERATE_FACTORY] && StationFactory.needPower(pc.mainRoom())) pc.addTask(UtilsTask.task(pc.mainRoom().factory, "OpFactory"))
            else if (obj = pc.needOpPowerSpawn()) pc.addTask(UtilsTask.task(obj, "OpPowerSpawn"))
            // else if (obj = pc.needOpLab()) pc.addTask(UtilsTask.task(obj, "OpLab"))
            else if (obj = pc.needOpMineral()) pc.addTask(UtilsTask.task(obj, "OpMineral"))
            else if (Game.time % 60 == 0 || pc.room.find(FIND_HOSTILE_CREEPS).length) {
                let mainRoom = pc.mainRoom();
                let obj = mainRoom.storage || mainRoom.terminal || mainRoom.powerSpawn
                if (obj) pc.addTask(UtilsTask.task(obj, "goToNearPop"));
            }
        }
    },
    exec() {
        if (Game.time % 3 != 0) return;
        ManagerFlags.getFlagsByPrefix("OPF")
            .forEach(flag => HelperError.catchError(() => pro.execRoom(flag)));
    }
}


global.StrategyFactoryPowerCreep = pro;

modules.strategy_deposits:
let MAX_COOL_DOWM = (() => {
    if (Game.shard.name == "shard3") return 60;
    if (Game.shard.name == "shard2") return 120;
    if (Game.shard.name == "shard1") return 120;
    if (Game.shard.name == "shard0") return 120;
    return 50;
})();
let BOOST_COOL_DOWN = 90
let ATTACKED_SLEEP = 1200
let AVOID_ROOMS = ["W30N51", "W30N50", "W34N50", "E44S40"]
let ATTACK_ROOMS = ['E50S31', 'E50S30', 'E50S29', 'E50S28', 'E50S27']


Creep.prototype.registerHarvestDepositCarrier = function () {
    let headTask = this.headTask();
    let flag = Game.flags[headTask.flagName];
    if (flag) {
        flag.memory.carriers = flag.memory.carriers || []
        if (!flag.memory.carriers.contains(this.id)) {
            flag.memory.carriers.push(this.id)
        }
    }
};


Creep.prototype.harvestDeposit = function () {
    let task = this.headTask();
    if (task.roomName != this.room.name) {
        this.goTo(task);
    } else {
        let deposit = Game.getObjectById(task["id"]);
        if (this.freeCapacity() < this.getPartCnt(WORK)) {
        }
        else if (deposit && this.harvest(deposit) == ERR_NOT_IN_RANGE) {
            this.goTo(deposit)
        }
        if (deposit && !this.memory.concated && this.pos.inRangeTo(deposit, 3)) this.concatDeposit()
    }
};

Creep.prototype.registerHarvestDeposit = function () {
    let headTask = this.headTask();
    let flag = Game.flags[headTask.flagName];
    if (flag) {
        flag.memory.harvesters = flag.memory.harvesters || []
        if (!flag.memory.harvesters.contains(this.id)) {
            flag.memory.harvesters.push(this.id)
        }
    }
    if (this.ticksToLive < 50 && this.ticksToLive % 3 == 0) {
        this.memory.dontPullMe = false;
    }
};

Creep.prototype.concatDeposit = function () {
    let headTask = this.headTask();
    this.memory.concated = true
    let flag = Game.flags[headTask.flagName];
    let pathTime = Math.min(300, 1470 - this.ticksToLive); // 预留30tick;
    if (flag && (!flag.memory.pathTime || flag.memory.pathTime > pathTime)) {
        flag.memory.pathTime = pathTime
    }
};

Creep.prototype.harvestDeposit = function () {
    let task = this.headTask();
    if (this.hits < this.hitsMax - 1000 && this.lastTask().flagName) {
        let flag = Game.flags[this.lastTask().flagName];
        if (flag && !this.memory.attacked) {
            flag.memory.beAttackTime = Game.time
            this.memory.attacked = true
        }
    }
    // this.suicide()
    if (task.roomName != this.room.name) {
        this.goTo(task);
    } else {
        let deposit = Game.getObjectById(task["id"]);
        if (this.freeCapacity() < this.getPartCnt(WORK)) {

        }
        else if (deposit && this.harvest(deposit) == ERR_NOT_IN_RANGE) {
            if (!this.pos.inRangeTo(deposit, 2) || deposit.pos.walkableAroundCnt(true) > 0) // 如果沒得走的時候就放棄，免得消耗太多cpu
                this.goTo(deposit)
        }
        if (deposit && this.pos.isNearTo(deposit) && !this.memory.concated) this.concatDeposit()
        // add by an_w
        flag1 = Game.flags[this.lastTask().flagName];
        if (((Game.time % 50 == 0 && this.pos.findInRange(FIND_HOSTILE_CREEPS, 8).length && !this.pos.isNearTo(deposit)) || this.hits < this.hitsMax) && (!flag1.memory.beAttackTime || Game.time > flag1.memory.beAttackTime + 1700)) {
            const em = this.pos.findInRange(FIND_HOSTILE_CREEPS, 8).filter(e => e.getActiveBodyparts(RANGED_ATTACK) > 0)
            if (em.length) {
                this.room.createFlag(this.pos, "raL3_" + this.memory.roomName, COLOR_RED)
            }
            // create attack flag if no attack flag in this room
            else {
                this.room.createFlag(this.pos, "raL4_"+this.memory.roomName, COLOR_RED)
            }
            flag1.memory.beAttackTime = Game.time
        }
        if ((flag1.memory.beAttackTime && Game.time >= flag1.memory.beAttackTime + 1650) || !flag1.memory.beAttackTime) {
            if (Game.flags["raL4_"+this.memory.roomName]) Game.flags["raL4_"+this.memory.roomName].remove()
            if (Game.flags["raL3_"+this.memory.roomName]) Game.flags["raL3_"+this.memory.roomName].remove()
        }
        
    }
};

Creep.prototype.carryDeposit = function () {
    let task = this.headTask();
    if (task.roomName != this.room.name) {
        this.goTo(task);
    } else {
        let flag = Game.flags[task.flagName];
        if (!flag) return;//
        let deposit = Game.getObjectById(task["id"]);
        if (deposit) {
            flag.memory.lastCooldown = deposit.lastCooldown;
            if (flag.memory.harvesters.length == 0 && deposit && deposit.lastCooldown >= MAX_COOL_DOWM) {
                flag.memory.waitTime = (flag.memory.waitTime || 0) + 1
            }
        }
        if (this.ticksToLive < (flag.memory.pathTime || 600) * 1.2 || this.storeFull() || flag.memory.waitTime > 100) {// 回家
            flag.memory.carriers = flag.memory.carriers || []
            if (!flag.memory.carriers.contains(this.id))
                flag.memory.carriers = flag.memory.carriers.without(this.id)
            this.popTask();
            this.addTask([UtilsTask.taskData("recycleCreep")])
            this.fillAllMainRoomStorage();
            this.execLastTask();
        }

        if (this.ticksToLive % 20 == 0) {
            let tombstone = this.pos.findClosestByPath(FIND_TOMBSTONES, { filter: e => e.store.getResTypeList().length && e.store.getUsedCapacity('energy') < e.store.getUsedCapacity(), range: 3 });
            this.carryAll(tombstone)
        }

        if (this.ticksToLive % 20 == 10) {
            let dropRes = this.pos.findClosestByPath(FIND_DROPPED_RESOURCES);
            if (dropRes) {
                this.addTask(UtilsTask.task(dropRes, "pickupRes", undefined, {
                    resType: dropRes.resourceType
                }))
                return;
            }
        }

        let needTransferCreep = flag.memory.harvesters.map(id => Game.getObjectById(id)).filter(e => e && e.storeUsed() >= 20).head();
        if (this.pos.isNearTo(needTransferCreep)) needTransferCreep.transfer(this, needTransferCreep.store.getResTypeList()[0]);
        else this.moveTo(needTransferCreep)

        if (!needTransferCreep && flag && this.pos.getRangeTo(flag) > 3) {
            this.moveTo(flag);
        }
    }
};

let pro = {

    createOrUpdateDepositMission(targetRoomName, depositData) {//
        if (AVOID_ROOMS.indexOf(targetRoomName) !== -1) return;
        // if (ATTACK_ROOMS.indexOf(targetRoomName) !== -1) {
        //     if (depositData.lastCooldown < 10 && !Game.flags['raL2_E49S31_keeper']) {
        //         (new RoomPosition(25, 24, targetRoomName)).createFlag('raL3_E49S31_1', COLOR_BLUE);
        //         (new RoomPosition(25, 6, 'E50S27')).createFlag('raL2_E49S31_keeper', COLOR_BLUE);
        //     }
        //     else if (depositData.lastCooldown > 67 && depositData.lastCooldown < 70) {
        //         console.log(depositData.lastCooldown)
        //         if (Game.flags['raL2_E49S31_keeper']) {
        //             Game.flags['raL2_E49S31_keeper'].remove()
        //         }
        //         if (Game.flags['raL3_E49S31_1']) Game.flags['raL3_E49S31_1'].remove()
        //     }
        // }
        let spawnRoomName = StationObserver.getClosedMyRoomName(targetRoomName);
        let flagName = "deposit_" + spawnRoomName + "_" + targetRoomName + "_" + depositData.x + "_" + depositData.y;
        if (!Memory.flags[flagName]) Memory.flags[flagName] = {}
        let flagMemory = Memory.flags[flagName];
        depositData.flagName = flagName;
        depositData.roomName = targetRoomName;
        for (let k in depositData) {
            flagMemory[k] = depositData[k];
        }
        if (!spawnRoomName || depositData.lastCooldown > MAX_COOL_DOWM) return;
        if (!Game.flags[flagName]) {
            (new RoomPosition(depositData.x, depositData.y, targetRoomName)).createFlag(flagName)
        }
    },
    trySpawnHarDeposits(room, memory, needBoost) {
        let body = ManagerCreeps.calcBodyPart({ [WORK]: 22, [CARRY]: 6, [MOVE]: 22 })
        let boostRes = { [BOOST_RES["harvest"][1]]: 30 * 22, [BOOST_RES["capacity"][1]]: 30 * 6 };
        let tasks = [UtilsTask.taskData("harvestDeposit", "registerHarvestDeposit", memory)]
        if (needBoost && StationLab.boostAble(room, boostRes)) {
            tasks.push(StationLab.generatorBoostResTask(boostRes, room).head())
        }
        StationHive.trySpawn(room, room.name, body, "harDeposits", tasks)
    },
    trySpawnCarryDeposits(room, memory, needBoost) {
        let body = []
        for (let i = 0; i < 25; i++)
            body.push(CARRY, MOVE)
        let tasks = [UtilsTask.taskData("carryDeposit", "registerHarvestDepositCarrier", memory)]
        let boostRes = { [BOOST_RES["capacity"][1]]: 30 * 25 };
        if (needBoost && StationLab.boostAble(room, boostRes)) {
            tasks.push(StationLab.generatorBoostResTask(boostRes, room).head())
        }
        StationHive.trySpawn(room, room.name, body, "carrierDeposits", tasks)
    },
    cleanFlag() {
        if (Game._depositCleanFlag) return;
        Game._depositCleanFlag = true
        ManagerFlags.getFlagsByPrefix("deposit").forEach(flag => {
            let roomName = flag.getRoomName();
            if (!roomName || !Game.rooms[roomName] || !Game.rooms[roomName].my) {
                flag.remove()
            }
        })
    },
    exec(room) {
        pro.cleanFlag();
        if ((Game.time + room.hashCode()) % 3 != 0) return;
        room.flags("deposit").forEach(flag => {
            flag.memory.flagName = flag.name
            if (!flag.memory.harvesters) flag.memory.harvesters = []
            else flag.memory.harvesters = flag.memory.harvesters.filter(id => Game.getObjectById(id))
            if (!flag.memory.carriers) flag.memory.carriers = []
            else flag.memory.carriers = flag.memory.carriers.filter(id => {
                let creep = Game.getObjectById(id)
                if (creep) return creep.headTask() && creep.headTask().taskName == "carryDeposit"
                return false
            });
            if (!flag.memory.walkableAroundCnt) {
                flag.memory.walkableAroundCnt = Math.min(flag.pos.walkableAroundCnt(), 3)
            }
            let offset = Math.min(flag.memory.walkableAroundCnt, 3) * 10 - 10
            if (Game.time < flag.memory.disappearTime && flag.memory.lastCooldown < MAX_COOL_DOWM + offset
                && (flag.memory.depositType != RESOURCE_MIST || flag.memory.lastCooldown < MAX_COOL_DOWM)) {// 如果是mist减半，少挖点，没啥用
                if (flag.memory.beAttackTime + ATTACKED_SLEEP > Game.time) return;
                let harTtlCreepCnt = flag.memory.harvesters.map(id => Game.getObjectById(id)).filter(e => e.spawning || e.ticksToLive > (flag.memory.pathTime || 0) + 150).length
                let carrierTtlCreepCnt = flag.memory.carriers.map(id => Game.getObjectById(id)).filter(e => e.spawning || e.ticksToLive > (flag.memory.pathTime || 0) + 300).length
                if (harTtlCreepCnt < flag.memory.walkableAroundCnt && (carrierTtlCreepCnt || harTtlCreepCnt < 2)) {
                    let needBoost = flag.memory.lastCooldown > BOOST_COOL_DOWN // 超过一定值后才boost，避免浪费资源
                        && !flag.memory.harvesters.map(id => Game.getObjectById(id)).find(e => e.memory.isBoost && (e.spawning || e.ticksToLive > (flag.memory.pathTime || 0) + 150))
                    pro.trySpawnHarDeposits(room, flag.memory, needBoost);
                    return;
                }
                if (carrierTtlCreepCnt < 1) {
                    // let needBoost = (flag.memory.lastCooldown<30 && flag.memory.walkableAroundCnt>=2) || (flag.memory.lastCooldown<50 && flag.memory.walkableAroundCnt>=3) || flag.memory.lastCooldown<10
                    // needBoost = needBoost&&!flag.memory.harvesters.map(id=>Game.getObjectById(id)).filter(e=>e.memory.isBoost).filter(e=>e.spawning||e.ticksToLive>(flag.memory.pathTime||0)+150).head()
                    let needBoost = false
                    pro.trySpawnCarryDeposits(room, flag.memory, needBoost);
                    return;
                }
            } else if (flag.memory.harvesters.length == 0 && flag.memory.carriers.length == 0) {
                flag.remove();
            } else if (flag.memory.harvesters.length != 0 && flag.memory.carriers.length == 0) {
                pro.trySpawnCarryDeposits(room, flag.memory);// 如果还有挖矿继续派兵
            }
            // HelperVisual.mapShowText(flag,flag.name)
        })
    }

}


global.StrategyDeposits = pro;

