/**
 * 过道防御
 */


Creep.prototype.registerDefenseHighWay=function () {
    if(this.spawning){
        let flag = this.headTaskFlag();
        if(flag)flag.memory.spawnTime = Game.time
        flag.memory.creep = this.id
    }
};

Creep.prototype.defenseHighWay=function () {
    let flag = this.headTaskFlag()
    this.autoHeal();
    if(!flag)return;
    let em = this.pos.findClosestByPath(FIND_HOSTILE_CREEPS,{filter:e=>e.body.find(e=>e.type==ATTACK)});//遇到 attack 拉开距离
    if(this.pos.inRangeTo(em,2)){
        em.range = 4
        let path = PathFinder.search(this.pos,em,{flee:true}).path;
        let code = this.moveByPath(path)
        this.rangedAttack(em);
        log(code,PathFinder.search(this.pos,em,{flee:true}))
        return;
    }

    if(!em)em=this.pos.findClosestByPath(FIND_HOSTILE_CREEPS,{filter:e=>!e.body.find(e=>e.type==HEAL||e.type==RANGED_ATTACK)});
    if(!this.memory.myDamage) this.memory.myDamage = this.possibleRangeDamage()
    if(!em)em=this.pos.findClosestByPath(FIND_HOSTILE_CREEPS,{filter:e=>e.possibleHealWithToughDamage()<this.memory.myDamage});
    if(!em)em=this.pos.findClosestByPath(FIND_HOSTILE_CREEPS);
    if(!em)em=this.pos.findClosestByPath(FIND_HOSTILE_POWER_CREEPS);

    if(em){
        this.moveTo(em);
        if(!em.pos.isNearTo(em))this.rangedAttack(em);
        else this.rangedMassAttack();
    }

    if(!em&&(!flag.pos.inRangeTo(em,4)||this.pos.isBorder())){
        this.moveTo(flag);
    }
};

let pro = {
    getDefenseHighWayData(room,spawnRoom){
        let sumDamage =  room.find(FIND_HOSTILE_CREEPS).map(e=>e.possibleDamage(false,2)).sum();// ra的全部伤害
        let sumHeal =  room.find(FIND_HOSTILE_CREEPS).map(e=>e.possibleHealDamage(1,false)).sum();// 全部奶量
        let maxToughDamage =  room.find(FIND_HOSTILE_CREEPS).map(e=>e.possibleToughBeHitsDamage(sumHeal)).maxBy(e=>e);// 单个能奶起来的最大值
        let rangeNeedCnt = Math.ceil(maxToughDamage/10+5)
        let toughNeedCnt = Math.ceil(sumDamage*0.3/100)
        let healNeedCnt = Math.ceil(sumDamage*0.3/12)||1
        let canSpawn = true

        let boostRes = {};
        let boostHeal = false
        let boostRangedAttack = false
        let boostFatigue = false
        if(rangeNeedCnt+toughNeedCnt+healNeedCnt<=25){// 不用boost
        }
        else if(rangeNeedCnt+toughNeedCnt+Math.ceil(healNeedCnt/4)<=25){// 要用boost 奶
            boostHeal = true
        } else if(Math.ceil(rangeNeedCnt/4)+toughNeedCnt+Math.ceil(healNeedCnt/4)<=25){// 要用boost 奶+ra
            boostRangedAttack = boostHeal = true
        }else if(Math.ceil(rangeNeedCnt/4)+toughNeedCnt+Math.ceil(healNeedCnt/4)<=40){// 要用boost 奶+ra+腿
            boostFatigue = boostRangedAttack = boostHeal = true
        }else{
            canSpawn = false
        }
        if(canSpawn){// 如果生的出来
            if(toughNeedCnt)boostRes[[BOOST_RES["damage"][2]]]=toughNeedCnt*30
            if(boostHeal)healNeedCnt = Math.ceil(healNeedCnt/4)
            if(boostHeal)boostRes[[BOOST_RES["heal"][2]]]=healNeedCnt*30
            if(boostRangedAttack)rangeNeedCnt = Math.ceil(rangeNeedCnt/4)
            if(boostRangedAttack)boostRes[[BOOST_RES["rangedAttack"][2]]]=rangeNeedCnt*30
            let MoveNeedCnt = rangeNeedCnt+toughNeedCnt+healNeedCnt
            if(boostFatigue)MoveNeedCnt = Math.ceil(MoveNeedCnt/4)
            if(boostFatigue)boostRes[[BOOST_RES["fatigue"][2]]]=MoveNeedCnt*30
            // log(rangeNeedCnt,toughNeedCnt,healNeedCnt,MoveNeedCnt)
            // log(boostRes)
            if (StationLab.boostAble(spawnRoom,boostRes)) {
                let task =  [
                    UtilsTask.taskFlag(flag,"defenseHighWay","registerDefenseHighWay")
                ]
                if(_.keys(boostRes).length)task.push(StationLab.generatorBoostResTask(boostRes).head())
                let body = ManagerCreeps.calcBodyPart([ [TOUGH,toughNeedCnt],[MOVE,MoveNeedCnt-1],[RANGED_ATTACK,rangeNeedCnt],[HEAL,healNeedCnt],[MOVE,1]])
                return {task:task, body:body}
            }
        }else {
            console.log(room.name+" damage too high to spawn defenseHighWay")
        }
    },
    checkDefense(flagName,room,spawnRoom){
        if(!Memory.flags[flagName])Memory.flags[flagName]={}
        if(!Memory.flags[flagName].spawnData&&(Memory.flags[flagName].spawnDefenseTime||0)<Game.time){
            let data = pro.getDefenseHighWayData(room,spawnRoom)
            if(data)Memory.flags[flagName].spawnData = data
        }
    },
    exec (room) {
        if(!room.storage)return;
        room.flags("defenserHighWay").forEach(flag=>{
            if(flag.memory.spawnData){
                if(StationHive.trySpawn(room, room.name,flag.memory.spawnData.body , "raL1", flag.memory.task)){
                    delete flag.memory.spawnData
                    flag.memory.spawnDefenseTime=Game.time+1200
                }
            }
        })
    }
}


global.StrategyDefenserHighWay=pro;

modules.strategy_minSizeRoom:
/**
 *
 */


Creep.prototype.registerMinRoom=function () {
    let mainRoom = this.mainRoom()
    if(!mainRoom)return;
    let flag = mainRoom.flags("minSizeRoom").head()
    if (flag) {
        flag.memory.creeps = flag.memory.creeps || []
        if(!flag.memory.creeps.contains(this.id))
            flag.memory.creeps.push(this.id)
    }
};


Creep.prototype.minRoom=function () {
    let task = this.lastTask();
    let obj = this.lastTaskObj();
    if(this.room.name!=task.roomName){
        this.moveTo(task,{visualizePathStyle: {stroke: '#67ffed'}})
    }
};

Creep.prototype.minRoomRecycleCreep=function () {
    if(this.ticksToLive<=1500)this.headTaskObj().recycleCreep(this);
}


Creep.prototype.minRoomUpgrade=function () {
    let flag= Game.flags[this.lastTask().id];
    if(!flag)return;
    if(!this.pos.isEqualTo(flag)) this.moveTo(flag)
    if(this.minRoomAutoBuild()==OK)return;
    this.minRoomAutoPick()
    let spawn = this.room.spawn.filter(e=>e.pos.isNearTo(flag)).head();
    let renew = "ERR"
    if(this.ticksToLive<1480&&((this.lastTask().lastRenewTimes||0)<=3)){//&&((this.lastTask().lastSpawnTime||0)<Game.time)
        renew = spawn.renewCreep(this)
    }
    // this.say(renew)
    if (spawn&&this.pos.isNearTo(spawn)) {
        if(renew=="ERR"){
            this.lastTask().lastRenewTimes = 0
            let task = [UtilsTask.task(spawn,"minRoomRecycleCreep")]
            let energyStructures = this.room[STRUCTURE_EXTENSION]
            StationHive.trySpawn(this.room,this.room.name,[WORK,MOVE],"suicide",task,{directions:[RIGHT],energyStructures:energyStructures})
        }
        if(renew==OK){
            this.lastTask().lastRenewTimes = (this.lastTask().lastRenewTimes||0)+1
        }
        // if(spawn.spawning)this.lastTask().lastSpawnTime = Game.time+1
        let container = this.pos.findInRange(FIND_STRUCTURES,1).filter(e=>e.structureType==STRUCTURE_CONTAINER&&e.store[RESOURCE_ENERGY]).head()
        if(container&&container.hits/container.hitsMax<0.95) this.repair(container);
        else{
            let rampart = spawn.pos.lookFor(LOOK_STRUCTURES).filter(e=>e.structureType==STRUCTURE_RAMPART).head();
            if(!rampart)spawn.pos.createConstructionSite(STRUCTURE_RAMPART)

            if(this.room.terminal){
                let terminal = this.room.terminal.pos.lookFor(LOOK_STRUCTURES).filter(e=>e.structureType==STRUCTURE_RAMPART).head();
                if(!rampart)terminal.pos.createConstructionSite(STRUCTURE_RAMPART)
            }

            rampart = this.pos.findInRange(FIND_STRUCTURES,1,{filter:e=>e.structureType==STRUCTURE_RAMPART&&e.my}).maxBy(e=>-e.hits)
            this.repair(rampart)
            // if(rampart&&rampart.hits==rampart.hitsMax&&this.storeUsed()>this.store.getFreeCapacity()){
            //     // let rampart = this.pos.findInRange(FIND_STRUCTURES,3).filter(e=>e.structureType==STRUCTURE_RAMPART).sort(((a, b) => a.hits-b.hits)).head()
            //     this.repair(rampart)
            // }
        }

    }
    this.upgradeController(this.room.controller);
    this.memory.dontPullMe = false;
};

Creep.prototype.minRoomHarvest = function () {
    let flag= this.room.flags("minSizeRoom").head();
    if(!flag||!flag.memory.sourcePos)return;
    let obj = this.lastTaskObj();
    let opos = flag.memory.sourcePos[obj.id].pos
    let pos = new RoomPosition(opos.x,opos.y,this.room.name);
    if((obj.energy+500)/obj.energyCapacity>(obj.ticksToRegeneration||300)/300&&obj.energy){
        this.harvest(obj);
    }
    this.minRoomAutoBuild()
    this.minRoomAutoPick()
    if(!this.pos.isEqualTo(pos)) this.moveTo(pos)
};


Creep.prototype.minRoomAutoBuild = function () {
    if(this.storeUsed()>0&&this.ticksToLive%2==0){
        let target = this.pos.findInRange(FIND_STRUCTURES,1,{filter:e=>e.structureType!=STRUCTURE_SPAWN&&e.structureType!=STRUCTURE_CONTAINER&&e.store&&e.store.getFreeCapacity(RESOURCE_ENERGY)>0}).head()
        if(target) return this.transfer(target,RESOURCE_ENERGY)
        target = this.pos.findInRange(FIND_CONSTRUCTION_SITES,3).head()
        if(target) return this.build(target);
    }
}
Creep.prototype.minRoomAutoPick = function () {
    if(!this.storeFull()){
        let target = this.pos.findInRange(FIND_DROPPED_RESOURCES,1).filter(e=>e.resourceType==RESOURCE_ENERGY).head()
        if(target) return this.pickup(target)
        target = this.pos.findInRange(FIND_TOMBSTONES,1).filter(e=>e.store[RESOURCE_ENERGY]).head()
        if(target) return this.withdraw(target,RESOURCE_ENERGY)
        target = this.pos.findInRange(FIND_STRUCTURES,1).filter(e=>e.structureType==STRUCTURE_CONTAINER&&e.store[RESOURCE_ENERGY]).head()
        if(target) return this.withdraw(target,RESOURCE_ENERGY)
    }
}

// Creep.prototype.build()


let pro = {
    workerBody : ManagerCreeps.calcBodyPart({ [WORK]: 12, [CARRY]: 10, [MOVE]: 12 }),
    findSourceHarvestPos (source){
        let cnt = 0;
        let finalPos = undefined;
        source.pos.nearPos().forEach(pos=>{
            if(pos.walkable()){
                let ableCnt = pos.walkableAroundCnt()
                if(cnt<ableCnt){
                    cnt = ableCnt;
                    finalPos = pos;
                }
            }
        })
        return finalPos;
    },
    generatorSourcePos (room,flag){
        // flag.memory.sourcePos = undefined
        if(!flag.memory.sourcePos){
            let pos1 = pro.findSourceHarvestPos(room.source[0])
            let pos2 = pro.findSourceHarvestPos(room.source[1])

            let exit1 = PathFinder.search(pos1, { pos: flag.pos, range: 0 }).path[0]
            let exit2 = PathFinder.search(pos2, { pos: flag.pos, range: 0 }).path[0]

            flag.memory.sourcePos = {
                [room.source[0].id]:{pos:{x:pos1.x,y:pos1.y},exit:{x:exit1.x,y:exit1.y}},
                [room.source[1].id]:{pos:{x:pos2.x,y:pos2.y},exit:{x:exit2.x,y:exit2.y}}
            }
        }
        // _.values(flag.memory.sourcePos).forEach(e=>{
        //     HelperVisual.showText(room.name,"*",e.pos)
        //     HelperVisual.showText(room.name,"!",e.exit)
        // })
    },
    tryCreateStructs(room,flag){
        new RoomPosition(flag.pos.x,flag.pos.y+1,room.name).createConstructionSite(STRUCTURE_SPAWN)
        if(!room.spawn.length||room.level<2)return;
        if(flag.memory.sourcePos){
            _.values(flag.memory.sourcePos).forEach(e=>{
                // new RoomPosition(e.pos.x,e.pos.y,room.name).nearPos(1)
                //     .filter(p=>(p.x!=e.exit.x||p.y!=e.exit.y)&&p.walkable())
                //     .map(e=>HelperVisual.showText(room.name,"*",e))
                let t = 0;
                new RoomPosition(e.pos.x,e.pos.y,room.name).nearPos(1)
                    .filter(p=>(p.x!=e.exit.x||p.y!=e.exit.y)&&(p.walkable()||p.lookFor(LOOK_STRUCTURES).length||p.lookFor(LOOK_CONSTRUCTION_SITES).length))
                    .take(4)
                    .forEach(p=>{
                        if(t!=0)p.createConstructionSite(STRUCTURE_EXTENSION)
                        else p.createConstructionSite(STRUCTURE_TOWER)
                        t++;
                    })
            })
        }
        // new RoomPosition(flag.pos.x-1,flag.pos.y-1,room.name).createConstructionSite(STRUCTURE_TOWER)
        // new RoomPosition(flag.pos.x-1,flag.pos.y+1,room.name).createConstructionSite(STRUCTURE_TOWER)
        new RoomPosition(flag.pos.x+1,flag.pos.y,room.name).createConstructionSite(STRUCTURE_TOWER)
        new RoomPosition(flag.pos.x-1,flag.pos.y,room.name).createConstructionSite(STRUCTURE_TOWER)
        new RoomPosition(flag.pos.x,flag.pos.y-1,room.name).createConstructionSite(STRUCTURE_TOWER)
        new RoomPosition(flag.pos.x+1,flag.pos.y-1,room.name).createConstructionSite(STRUCTURE_TERMINAL)
        new RoomPosition(flag.pos.x+1,flag.pos.y+1,room.name).createConstructionSite(STRUCTURE_CONTAINER)
    },
    workWithNoRenew (room){
        _.values(room.memory[StationSources.stationName]).filter(e=>Game.getObjectById(e.id).energy)
            .sort((a,b)=>Game.getObjectById(b.id)?Game.getObjectById(b.id).energy-Game.getObjectById(a.id).energy:0) // 如果有视野 按能量多少从大到小排序
            .forEach(data=>{
                // room[data["id"]].pos.findInRange(FIND_STRUCTURES,1).filter(e=>e.structureType = STRUCTURE_WALL).length;
                let posLen = room[data["id"]].pos.nearPos(1).filter(e=>e.walkable()).length
                let targetCnt = posLen*1.5 - room.creeps("minRoomWorker").filter(e=>e.headTask()&&e.headTask().id == data["id"]).length;
                if(Math.min(6,Math.ceil(targetCnt))>0){
                    let creep = room.creeps("minRoomWorker").filter(e=>e.storeEmpty()&&e.isFree()).head()
                    // log(StationWork.getLowLevelWorkerBodyConfig(spawnRoom,false))
                    if(creep)creep.addTask(StationSources.generatorReleaseAbleHarTask(data))
                }
            });

        room.creeps("minRoomWorker").filter(e=>!e.storeEmpty()&&e.isFree()).forEach(creep=>{
            if(StationWork.constructionNeedBuild(creep.mainRoom())){
                creep.addTask(StationWork.generatorBuildTask(creep))
            } else {
                creep.addTask(StationUpgrade.generatorUpgradeTask(room));
            }
        })
    },
    exec (room) {
        let flag = room.flags("minSizeRoom").head();
        let tasks = [UtilsTask.task(room.controller,"minRoom","registerMinRoom")];
        let hostileCnt = room.find(FIND_HOSTILE_CREEPS,{filter:e => e.owner.username != "Invader" && e.body.filter(e=>e.type==HEAL).length >= 5 }).length;
        if(hostileCnt){
            flag.memory.hostileFindTime = Game.time // 如果发现敌人就暂时不生小兵，躲几波
        }
        if (room.creeps("minRoomWorker",false).length < 3 && ((Game.time+room.hashCode())%7==0) && Game.time>(flag.memory.hostileFindTime||0)+1500) {
            // if(!Game.time%3==0)return;
            // let spawnRoom = Game.rooms.E7N18//?Game.rooms.E7N18:StationHive.getClosestSpawnRoom(room,6,6)
            let spawnRoom = StationHive.getClosestSpawnRoom(room,6,6)//Game.rooms.W8N7//?Game.rooms.W8N7:StationHive.getClosestSpawnRoom(room,6,6)
            // if(!spawnRoom)spawnRoom = Game.rooms.E7N18
            if(!spawnRoom){
                log("no active able room");
                return;
            }
            // log(spawnRoom.name)
            StationHive.trySpawn(spawnRoom,room.name,pro.workerBody,"minRoomWorker", tasks)
        }
        flag.memory.creeps = flag.memory.creeps || []
        flag.memory.creeps = flag.memory.creeps.filter(id=>Game.getObjectById(id))
        let creeps = flag.memory.creeps.map(id=>Game.getObjectById(id)).filter(e=>e.room.name == room.name).sort((a,b)=>b.ticksToLive-a.ticksToLive)
        pro.generatorSourcePos(room,flag);
        if(Game.time%30==0){ 
            pro.tryCreateStructs(room,flag);
        }
        if(room.level<2||!room.spawn.length){//room.constructionSite.length||
            creeps.filter(e=>e.headTask()&&e.headTask().taskName=="minRoom").forEach(e=>e.memory.tasks = [])
            pro.workWithNoRenew(room)
            return;
        }
        let needExchange = creeps.filter(e=>e.memory.tasks.length!=2).length
        if((Game.time+room.hashCode())%600==0||needExchange){//交换任务
            let source = room.source.sort((a,b)=> a.id.localeCompare(b.id))
            if(creeps.length>=1){
                creeps.head().memory.tasks = [tasks[0],UtilsTask.task(source[0],"minRoomHarvest")]
            }
            if(creeps.length==3){
                creeps[1].memory.tasks = [tasks[0],UtilsTask.task(source[1],"minRoomHarvest")]
            }
            if(creeps.length>1){
                creeps.last().memory.tasks = [tasks[0],UtilsTask.taskFlag(flag,"minRoomUpgrade")]
            }
        }
    }
}


global.StrategyMinSizeRoom=pro;

modules.strategy_marketPrice:
/**
 *  价格计算模块：
 *  这里只提供这个方法：
 *  StrategyMarketPrice.getSellPrice()
 *  返回一个map key是资源 value是售价 单位cr
 *
 *  StrategyMarketPrice.updateSellPrice(true)
 */

let COMPRESSION_SET = new Set([RESOURCE_UTRIUM_BAR,RESOURCE_LEMERGIUM_BAR,RESOURCE_KEANIUM_BAR,RESOURCE_ZYNTHIUM_BAR,RESOURCE_GHODIUM_MELT,RESOURCE_OXIDANT,RESOURCE_REDUCTANT,RESOURCE_PURIFIER,RESOURCE_BATTERY]);
let BASE_RESTYPE = new Set([RESOURCE_ENERGY,"U","L","K","Z","X","O","H","ops"])
let BLUE = [RESOURCE_DEVICE,RESOURCE_CIRCUIT,RESOURCE_MICROCHIP,RESOURCE_TRANSISTOR,RESOURCE_SWITCH,RESOURCE_WIRE];
let YELLOW = [RESOURCE_MACHINE,RESOURCE_HYDRAULICS,RESOURCE_FRAME,RESOURCE_FIXTURES,RESOURCE_TUBE,RESOURCE_ALLOY];
let PINK = [RESOURCE_ESSENCE,RESOURCE_EMANATION,RESOURCE_SPIRIT,RESOURCE_EXTRACT,RESOURCE_CONCENTRATE,RESOURCE_CONDENSATE];
let GREEN = [RESOURCE_ORGANISM,RESOURCE_ORGANOID,RESOURCE_MUSCLE,RESOURCE_TISSUE,RESOURCE_PHLEGM,RESOURCE_CELL];
let BASE_DEPOSITS = [RESOURCE_SILICON,RESOURCE_BIOMASS,RESOURCE_METAL,RESOURCE_MIST]; // 0 级
let L1_DEPOSITS = [RESOURCE_WIRE,RESOURCE_ALLOY,RESOURCE_CONDENSATE,RESOURCE_CELL]; // 1 级
let DEPO_MAP = (function (){
    let mp = {};
    BLUE.forEach(e=>mp[e] = RESOURCE_SILICON);
    YELLOW.forEach(e=>mp[e] = RESOURCE_METAL);
    PINK.forEach(e=>mp[e] = RESOURCE_MIST);
    GREEN.forEach(e=>mp[e] = RESOURCE_BIOMASS);
    return mp;
})();

let PRICE_TOLERANCE = 0.1 // 贱卖的价格 比例
let TARGET_STORE_CNT = 100000 // 目标不讲价的卖的价格 的存储数量 超过这个值开始贱卖 目标 0.1m
let DEPO_SET = new Set(BLUE.concat(YELLOW).concat(PINK).concat(GREEN))
// 挖一个的成本大概在3.8 - 5 左右 取决于boost没有 s2 和 s3， 能量价格也不一样，挖到多少不挖也不一样，见仁见智吧
// 挖到100 大概成本是3.8-7左右
let DEFAULT_DEPO_MUL =  3// 默认成本价格 ，这个不会从市场算了，市场买的价格虚高
let DEFAULT_PRICE = // 默认资源价格//如果不能从市场算的话//所有资源都会从这边算//如果低于这个价格按这个价格算
    (function () {
        if(Game.shard.name=="shard3")
            return  {"energy":0.5, "U":1.5, "L":0.5, "K":0.7, "Z":0.3, "X":4, "O":0.5, "H":1.1,"ops":1,}
        if(Game.shard.name=="Screeps.Cc")
            return  {"energy":1, "U":0.3, "L":0.3, "K":0.3, "Z":0.3, "X":0.95, "O":0.1, "H":0.1,"ops":1,}
        else
            return {"energy":1.5, "U":1.8, "L":1, "K":1, "Z":1, "X":8, "O":1.8, "H":1,}
})();

let MAX_DELAY = 86400/16 ; // 更新商品价格的延迟  大概6小时跟新一次



let pro = {
    _lastTick : -1e9, //上次更新时间
    // _baseResPrice:{},// 基础资源价格
    _depoResPrice:{},// 商品交易价格
    _depoResPriceStddev:{},// 商品交易方差
    // _avgBaseDepoProfit:{},// 平均每个基础商品的交易利润
    _depoMinSellPrice:{},

    // 计算合成需要的资源，计算利润
    _depoNeedPerCommodity : {},// 商品合成需要多少 单位基础商品
    _depoCostPerCommodity : {},// 商品合成需要多少cr 单位在每个基础商品上需要花多少额外资源的价格

    _depoSellPrice :{},// final sell price
    _depoMaxProfit :{},// 基础depo的最大利润，可以拿来倒买倒卖

    getSellPrice (){
        pro.updatePrice();
        // log( pro._depoSellPrice)
        return pro._depoSellPrice;
    },

    getAutoBuyDepoPrice(){
        pro.updatePrice();
        let priceMap = {};
        [RESOURCE_BIOMASS,RESOURCE_SILICON,RESOURCE_METAL,RESOURCE_MIST].forEach(e=>{
            priceMap[e] = pro._depoMaxProfit[e]/2
        });
        [RESOURCE_WIRE,RESOURCE_ALLOY,RESOURCE_CONDENSATE,RESOURCE_CELL].forEach(e=>{
            priceMap[e] = pro._depoMaxProfit[DEPO_MAP[e]]*2.5
        });
        return priceMap;
    },

    updatePrice (){
        if(pro._lastTick>=Game.time)return;
        // let time = Game.cpu.getUsed();
        pro.updateDepoPrice();
        pro.updateDepoHistroyPrice();
        pro.updateSellPrice()
        pro._lastTick=Game.time+MAX_DELAY;
        // log(Game.cpu.getUsed() - time) // 更新一次 大概消耗 2cpu
    },

    updateSellPrice (show=false) {
        let profitMap = {} // 利润
        pro._depoSellPrice = {};
        if(show)console.log("基础价格:","商品","均价","最低售价","利润","售价比")

        let myRooms = _.values(Game.rooms).filter(e=>e.my)

        let depoRatioMap = L1_DEPOSITS.map(e=>[DEPO_MAP[e],myRooms.map(room=>StationCarry.roomMassStoreCnt(room,e)).sum()/TARGET_STORE_CNT]).toMap()

        let energyPrice = pro.getResTypeHistory(RESOURCE_ENERGY)
        let defaultDepoPrice = DEFAULT_DEPO_MUL*energyPrice
        for(let k in DEPO_MAP){
            let storeRatio = Math.min(Math.sqrt(depoRatioMap[DEPO_MAP[k]]),1.414)-1; //sqrt(x)
            let minSellPrice = pro._depoResPrice[k]*(1-PRICE_TOLERANCE*storeRatio); // 最少需要的价格
            let profit = minSellPrice/pro._depoNeedPerCommodity[k] - pro._depoCostPerCommodity[k];
            if(show)console.log(k,pro._depoResPrice[k],minSellPrice,profit,1-PRICE_TOLERANCE*storeRatio)
            profitMap[k] = profit;
            pro._depoMinSellPrice[k] = minSellPrice;
            if(profit>defaultDepoPrice*1.5)pro._depoSellPrice[k] = minSellPrice;// 必须有的赚才卖
        }


        if(show)console.log("修正价格:","商品","售价","均价差距比","利润");
        [BLUE,YELLOW,PINK,GREEN].forEach(series=>{ // 按利润线均匀出售
            let maxProfit = 0;
            series.forEach(e=>{if(maxProfit < profitMap[e])maxProfit = profitMap[e]})
            pro._depoMaxProfit[DEPO_MAP[series[0]]]=maxProfit
            series.forEach(e=>{if(maxProfit > profitMap[e]){
                // let oldPrice = pro._depoSellPrice[e];
                pro._depoSellPrice[e] = (maxProfit+pro._depoCostPerCommodity[e])*pro._depoNeedPerCommodity[e] // 修正后的价格
                if(show)console.log(e,pro._depoSellPrice[e],pro._depoSellPrice[e]/(pro._depoResPrice[e]||1),maxProfit);
            }else {
                if(show)console.log(e,pro._depoSellPrice[e],pro._depoSellPrice[e]/(pro._depoResPrice[e]||1),maxProfit);
            }})
            // series.forEach(e=> delete pro._depoSellPrice[e])
        })

    },

    getHistory(resType) {
        return Game.market.getHistory(resType)||[];//historys //
    },

    updateDepoHistroyPrice (){
        let historyOrders =  pro.getHistory();

        let amount = {}
        let priceSum = {}
        let stddevDays = {}
        let stddev = {}
        historyOrders.forEach(e=>{
            if(!DEPO_SET.has(e.resourceType))return;
            if(e.stddevPrice>e.avgPrice*0.4) return;
            priceSum[e.resourceType] = ( priceSum[e.resourceType] || 0 ) + e.avgPrice*e.volume;
            amount[e.resourceType] = ( amount[e.resourceType] || 0 ) + e.volume;
            stddevDays[e.resourceType] = (stddevDays[e.resourceType]||0)+1;
            stddev[e.resourceType] = (stddev[e.resourceType]||0)+e.stddevPrice;
        });

        let depoResPrice = {};
        let depoResPriceStddev = {};
        let sumBaseDepoProfit = {};
        let cntBaseDepoProfit = {};
        for(let resType in priceSum) {
            let BaseDepo = DEPO_MAP[resType];

            depoResPrice[resType] = priceSum[resType]/amount[resType] ;
            depoResPriceStddev[resType] = stddev[resType]/stddevDays[resType];
            sumBaseDepoProfit[BaseDepo] = (sumBaseDepoProfit[BaseDepo]||0) + priceSum[resType] - pro._depoCostPerCommodity[resType]* pro._depoNeedPerCommodity[resType]*amount[resType];
            cntBaseDepoProfit[BaseDepo] = (cntBaseDepoProfit[BaseDepo]||0) + amount[resType] * pro._depoNeedPerCommodity[resType];
        }
        // let avgBaseDepoProfit = {}
        // for(let resType in sumBaseDepoProfit) {
        //     avgBaseDepoProfit[resType] = sumBaseDepoProfit[resType]/cntBaseDepoProfit[resType]
        // }
        pro._depoResPrice = depoResPrice;
        pro._depoResPriceStddev = depoResPriceStddev;
        // pro._avgBaseDepoProfit = avgBaseDepoProfit;
        // log(depoResPrice);
        // log(depoResPriceStddev);
        // log(avgBaseDepoPrice);

    },
    getBaseResTypeHistory  (){ // 基础资源的价格
        let historyOrders =  pro.getHistory();
        let history = {}
        historyOrders.forEach(e=>{
            if(!BASE_RESTYPE.has(e.resourceType))return;
            if(e.stddevPrice>e.avgPrice&&e.stddevPrice>=1&&e.resourceType!==RESOURCE_ENERGY)return; // 排除有些人挂单换cr
            // if(e.date==date)return;// 排除当天交易
            if(!history[e.resourceType])
                history[e.resourceType] = [];
            history[e.resourceType].push(e)
        })
        let out = {}
        for(let resType of BASE_RESTYPE){
            let hisArr = history[resType];
            if(hisArr){
                let avg = _.sum(hisArr.map(e=>e.avgPrice))/hisArr.length
                if(avg>DEFAULT_PRICE[resType])out[resType] = avg;
                else out[resType] = DEFAULT_PRICE[resType];
            }else {
                out[resType] = DEFAULT_PRICE[resType]
            }
        }

        // Object.entries(priceSum).sort((a,b)=>a[1]-b[1]).map(e=>[e[0],e[1],e[1]/amount[e[0]],amount[e[0]]]).forEach(e=>console.log(e));
        return out
    },
    getResTypeHistory  (resType){ // 资源平均价格价格
        let list = pro.getHistory(resType);
        let history = list.length&&list.filter(e=>!(e.stddevPrice>e.avgPrice&&e.stddevPrice>=1)||resType=='energy')// 排除有些人挂单换cr
        if(!history)return 0
        return _.sum(history.map(e => e.avgPrice)) / history.length ||10// 平均值
    },
    updateDepoPrice (){ // 计算合成的成本
        let price = pro.getBaseResTypeHistory();
        let energyPrice = pro.getResTypeHistory(RESOURCE_ENERGY)
        let defaultDepoPrice = DEFAULT_DEPO_MUL*energyPrice
        let getPrice = function (resType){
            // let data = price.list.filter(e=>e._id==resType).head();
            let data = price[resType];
            if(resType == "G") return getPrice("L")+getPrice("U")+getPrice("O")+getPrice("K") // g默认用原矿
            if(BASE_DEPOSITS.contains(resType))return defaultDepoPrice;
            return data
        };
        let getAllPrice = function (resMap){
            return _.sum(_.keys(resMap).map(e=>getPrice(e)*resMap[e]))
        }
        let getResCnt = function (resType,cnt,resMap){
            let amount = COMMODITIES[resType].amount
            for(let base in COMMODITIES[resType].components){
                let t = COMMODITIES[resType].components[base]*cnt/amount
                if(COMMODITIES[base]&&!COMPRESSION_SET.has(resType)){
                    getResCnt(base,t,resMap)
                }else{
                    resMap[base]=(resMap[base]||0)+t
                    // log(base,t)
                }
            }
            if(COMMODITIES[resType].level){
                let base = "ops"
                let batch = Math.ceil(1000/COMMODITIES[resType].cooldown)// 每1000 tick 能反应几次
                let amount = COMMODITIES[resType].amount
                resMap[base]=(resMap[base]||0)+(100/batch)/amount
            }
            return resMap
        };
        pro._depoNeedPerCommodity = {};
        pro._depoCostPerCommodity = {};
        [BLUE,YELLOW,PINK,GREEN].forEach(e=>{
            e.forEach(sellDepo=>{
                let mp = {}// 单个资源需要多少
                let basePrice = getAllPrice(getResCnt(sellDepo,1,mp)) // 基础价格
                // let sellDepoPrice = getPrice(sellDepo)
                let depo = _.keys(mp).filter(e=>BASE_DEPOSITS.contains(e)).head()
                // let sellPrice = ((basePrice/mp[depo])+100)*mp[depo]
                // (sellDepoPrice - basePrice)/mp[depo]
                // let opsPerDepo = mp["ops"]/mp[depo]
                // sellPrice
                // opsPerDepo

                // console.log(sellDepo,mp[depo],basePrice,basePrice/mp[depo])//,basePrice/sellDepoPrice
                // log(mp)
                pro._depoNeedPerCommodity[sellDepo] = mp[depo];
                pro._depoCostPerCommodity[sellDepo] = basePrice/mp[depo];
            });
            // console.log()
        })

    },
    
}
/**
 * 计算所有商品的价格和利润，并可视化打印
 */
pro.calculateAllCommoditiesProfit = function(showDetail = false, outputToConsole = true) {
    // 更新价格数据
    pro.updatePrice();
    
    // 获取基础资源价格
    let basePrices = pro.getBaseResTypeHistory();
    
    // 获取能量价格
    let energyPrice = pro.getResTypeHistory(RESOURCE_ENERGY);
    
    // 存储所有商品的计算结果
    let allCommodities = {};
    
    // 计算函数：递归计算商品所需基础资源
    let calculateBaseComponents = function(resType, amount = 1, visited = new Set()) {
        if (visited.has(resType)) return {}; // 防止循环依赖
        visited.add(resType);
        
        let components = {};
        
        // 如果是基础资源
        if (BASE_RESTYPE.has(resType) || BASE_DEPOSITS.includes(resType)) {
            components[resType] = amount;
            return components;
        }
        
        // 获取商品定义
        let commodity = COMMODITIES[resType];
        if (!commodity) {
            console.log(`Warning: No definition for ${resType}`);
            return {};
        }
        
        // 如果有组件，递归计算
        if (commodity.components) {
            for (let comp in commodity.components) {
                let compAmount = commodity.components[comp] * amount / (commodity.amount || 1);
                let subComponents = calculateBaseComponents(comp, compAmount, new Set(visited));
                
                // 合并组件
                for (let subComp in subComponents) {
                    components[subComp] = (components[subComp] || 0) + subComponents[subComp];
                }
            }
        }
        
        // 添加ops成本
        if (commodity.cooldown && commodity.level > 0) {
            let batch = Math.ceil(1000 / commodity.cooldown); // 每1000 tick能反应几次
            let opsAmount = (100 / batch) * amount / (commodity.amount || 1);
            components["ops"] = (components["ops"] || 0) + opsAmount;
        }
        
        return components;
    };
    
    // 计算所有商品
    for (let resType in COMMODITIES) {
        let commodity = COMMODITIES[resType];
        
        // 计算基础组件成本
        let baseComponents = calculateBaseComponents(resType, 1);
        
        // 计算总成本
        let totalCost = 0;
        let componentDetails = {};
        
        for (let comp in baseComponents) {
            let compPrice = 0;
            
            if (comp in basePrices) {
                compPrice = basePrices[comp];
            } else if (comp === "G") {
                // G是特殊计算
                compPrice = basePrices["L"] + basePrices["U"] + basePrices["O"] + basePrices["K"];
            } else {
                // 尝试获取历史价格
                compPrice = pro.getResTypeHistory(comp) || 0;
            }
            
            let compCost = baseComponents[comp] * compPrice;
            totalCost += compCost;
            componentDetails[comp] = {
                amount: baseComponents[comp],
                price: compPrice,
                cost: compCost
            };
        }
        
        // 获取市场价格
        let marketPrice = 0;
        if (DEPO_SET.has(resType) && pro._depoResPrice[resType]) {
            marketPrice = pro._depoResPrice[resType];
        } else {
            // 尝试从市场历史获取
            marketPrice = pro.getResTypeHistory(resType) || 0;
        }
        
        // 计算利润
        let profit = marketPrice - totalCost;
        let profitMargin = totalCost > 0 ? (profit / totalCost * 100) : 0;
        
        // 计算建议售价（成本 + 20% 利润）
        let suggestedPrice = marketPrice*1.05
        
        // 存储结果
        allCommodities[resType] = {
            level: commodity.level || 0,
            totalCost: totalCost,
            marketPrice: marketPrice,
            profit: profit,
            profitMargin: profitMargin,
            suggestedPrice: suggestedPrice,
            components: baseComponents,
            componentDetails: componentDetails
        };
    }
    
    // 按等级和利润排序
    let sortedCommodities = Object.entries(allCommodities)
        .sort((a, b) => {
            // 先按等级排序
            if (a[1].level !== b[1].level) {
                return a[1].level - b[1].level;
            }
            // 再按利润排序（降序）
            return b[1].profit - a[1].profit;
        });
    
    // 生成HTML输出
    let htmlOutput = generateCompactCommoditiesHTML(sortedCommodities, energyPrice);
    
    // 输出到控制台
    if (outputToConsole) {
        console.log(htmlOutput);
    }
    
    // 保持返回值不变
    return {
        commodities: allCommodities,
        html: htmlOutput
    };
};
/**
 * 生成紧凑的商品利润分析表格
 */
function generateCompactCommoditiesHTML(sortedCommodities, energyPrice) {
    let timestamp = Game.time;
    
    // 按利润状态分组
    let profitable = [];
    let neutral = [];
    let unprofitable = [];
    
    sortedCommodities.forEach(([resType, data]) => {
        if (data.profit > 0) {
            profitable.push({resType, data});
        } else if (data.profit === 0) {
            neutral.push({resType, data});
        } else {
            unprofitable.push({resType, data});
        }
    });
    
    // 计算总利润
    let totalProfit = profitable.reduce((sum, item) => sum + item.data.profit, 0);
    
    // 生成紧凑的HTML - 单行表格形式
    let html = '<div style="font-family:Consolas,Monaco,\'Courier New\',monospace;background:#1a1a1a;color:#e0e0e0;padding:2px;border-radius:2px;font-size:11px;line-height:1.1;">';
    
    // 标题行
    html += '<div style="display:flex;justify-content:space-between;margin-bottom:2px;padding-bottom:1px;border-bottom:1px solid #333;">';
    html += '<span style="color:#4FC3F7;font-weight:bold;">📊 商品利润分析</span>';
    html += '<span style="color:#BBB;">能量:' + energyPrice.toFixed(2) + '|总计:' + sortedCommodities.length + '</span>';
    html += '</div>';
    
    // 生成单行表格（包含标题栏）
    html += generateSingleLineTable(profitable, 'profit', '✓', '有利润');
    html += generateSingleLineTable(neutral, 'neutral', '○', '持平');
    html += generateSingleLineTable(unprofitable, 'loss', '✗', '亏损');
    
    // 汇总信息
    html += '<div style="margin-top:3px;padding:2px;background:#252525;border-radius:1px;font-size:10px;display:flex;justify-content:space-between;">';
    html += '<span>盈利:' + profitable.length + '种</span>';
    html += '<span style="color:#4CAF50">总利润:' + totalProfit.toFixed(2) + '</span>';
    html += '<span>持平:' + neutral.length + '种</span>';
    html += '<span style="color:#F44336">亏损:' + unprofitable.length + '种</span>';
    html += '</div>';
    
    html += '</div>';
    
    return html;
}

/**
 * 生成单行表格（每个商品一行）
 */
function generateSingleLineTable(items, status, statusIcon, statusText) {
    if (items.length === 0) return '';
    
    let statusColor = status === 'profit' ? '#4CAF50' : 
                     status === 'neutral' ? '#FFC107' : 
                     '#F44336';
    
    let bgColor = status === 'profit' ? 'rgba(76, 175, 80, 0.05)' : 
                  status === 'neutral' ? 'rgba(255, 193, 7, 0.05)' : 
                  'rgba(244, 67, 54, 0.05)';
    
    let html = '<div style="margin:1px 0 2px 0;">';
    
    // 状态标题
    html += '<div style="color:' + statusColor + ';font-size:10px;margin-bottom:1px;padding-left:2px;">' + statusIcon + ' ' + statusText + ' (' + items.length + '种)</div>';
    
    // 表格标题栏
    html += '<div style="display:flex;align-items:center;background:#333;margin:1px 0;padding:2px 4px;border-radius:1px;font-size:10px;color:#AAA;border-bottom:1px solid #444;">';
    html += '<div style="width:15px;text-align:center;">Lv</div>';
    html += '<div style="width:85px;">商品</div>';
    html += '<div style="width:50px;text-align:right;">成本</div>';
    html += '<div style="width:50px;text-align:right;">市价</div>';
    html += '<div style="width:50px;text-align:right;">利润</div>';
    html += '<div style="width:55px;text-align:right;">利润率</div>';
    html += '<div style="width:50px;text-align:right;">建议价</div>';
    html += '<div style="width:15px;text-align:center;">状态</div>';
    html += '</div>';
    
    // 数据行
    items.forEach((item) => {
        let resColor = RES_COLOR_MAP[item.resType] || '#9E9E9E';
        let profitColor = item.data.profit >= 0 ? '#4CAF50' : '#F44336';
        let marginColor = item.data.profitMargin >= 0 ? '#4CAF50' : '#F44336';
        let priceColor = item.data.marketPrice > item.data.totalCost ? '#4CAF50' : '#F44336';
        
        // 每行一个商品
        html += '<div style="display:flex;align-items:center;background:' + bgColor + ';margin:1px 0;padding:2px 4px;border-radius:1px;border-left:2px solid ' + resColor + ';">';
        
        // 等级
        html += '<div style="width:15px;text-align:center;font-size:9px;color:#888;">' + (item.data.level||0) + '</div>';
        
        // 商品名称
        html += '<div style="width:85px;color:' + resColor + ';font-weight:bold;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + item.resType + '</div>';
        
        // 成本
        html += '<div style="width:50px;text-align:right;font-size:10px;">' + item.data.totalCost.toFixed(1) + '</div>';
        
        // 市价
        html += '<div style="width:50px;text-align:right;font-size:10px;color:' + priceColor + '">' + item.data.marketPrice.toFixed(1) + '</div>';
        
        // 利润
        html += '<div style="width:50px;text-align:right;font-size:10px;color:' + profitColor + '">' + item.data.profit.toFixed(1) + '</div>';
        
        // 利润率
        html += '<div style="width:55px;text-align:right;font-size:10px;color:' + marginColor + '">' + item.data.profitMargin.toFixed(1) + '%</div>';
        
        // 建议售价
        html += '<div style="width:50px;text-align:right;font-size:10px;color:#BBB">' + item.data.suggestedPrice.toFixed(1) + '</div>';
        
        // 状态图标
        html += '<div style="width:15px;text-align:center;color:' + statusColor + ';font-size:10px;">' + statusIcon + '</div>';
        
        html += '</div>';
    });
    
    html += '</div>';
    return html;
}

