let pro={
    cloneTask(task,taskName=undefined){
        let newTask = {};
        for (let i in task) {
            newTask[i] = task[i];
        }
        if(taskName)newTask.taskName=taskName;
        return newTask;
    },
    task (obj,taskName,registerFuncName,ops = {}) {
        let newTask ={
            taskName:taskName,
            id:obj.id,
            roomName:obj.room.name,
            x:obj.pos.x,
