let base36 = Math.pow(36,10)
randomId = ()=>_.padLeft(Math.ceil(Math.random()*base36).toString(36).toLocaleUpperCase(),10,"0")

let posCodeNumberMap = {};
let posCodeCharMap = {};
// pos 转换 char 用的
(function (){
    let a = 'a'.charCodeAt(0)
    let A = 'A'.charCodeAt(0)
    for(let i=0;i<25;i++){
        let b = String.fromCharCode(a+i)
        let j = 25+i
        let B = String.fromCharCode(A+i)
        posCodeNumberMap[i] = b
        posCodeCharMap[b] = i
        posCodeNumberMap[j] = B
        posCodeCharMap[B] = j
    }
}())


let pro={
    randomGet (array) {
        return array[Math.floor(array.length*Math.random())]
    },
    getBodyEnergyNeed(body){
        let need=0;
        body.forEach(e=>{if(BODYPART_COST[e])need+=BODYPART_COST[e]});
        return need;
    },
    /*
    let str = Utils.encodePosArray(Memory.rooms.W5N8.structMap.constructedWall.map(e=>{return {x:e[0],y:e[1]}}))
    log(str)
    let arrs = Utils.decodePosArray(str)
    log(arrs)
    log(Memory.rooms.W5N8.structMap.constructedWall.map(e=>{return {x:e[0],y:e[1]}}))
    */
    encodePosArray (posArray){
        return posArray.map(e=>posCodeNumberMap[e.x]+posCodeNumberMap[e.y]).reduce((a,b)=>a+b,"")
    },
    decodePosArray (string){
        let out = []
        for(let i=0;i<string.length;i+=2){
            out.push({x:posCodeCharMap[string[i]],y:posCodeCharMap[string[i+1]]})
        }
        return out;
    },
    hashCode (str){
        let hash = 5381;
        for (let i = 0; i < str.length; i++) {
            let char = str.charCodeAt(i);
            hash = ((hash << 5) + hash) + char; /* hash * 33 + c */
        }
        return hash
    },
    //线性同余随机数
    rnd ( seed ){
        return ( seed * 9301 + 49297 ) % 233280; //为何使用这三个数?
    },
    randomInt(start,end){
        if(end==undefined){
            end = start
            start = 0
        }
        let range = end-start
        return start + Math.floor(Math.random()*range)
    }
};


global.Utils=pro;

modules.war_teamControl:
/**
 * flag.memory.mode
 *  line 小队变成 直线仅四人小队 ，否则退化成 move
 *  move 移动,跑到 flag 的位置
 *  attack 搜索，歼灭 creep, 只有这个模式会 帮助其他人
 *  rash 激进模式，不算伤逃跑,attack模式2
 *  flee 风筝模式,保持距离
 *
 *
 * flag.memory.forceStructs
 *  true 专注建筑
 *  false 也打爬 (工兵除外)
 */




let pro = {
    checkMoveMode(flag){
        let creeps = flag._creeps;
        let currRoom = flag._creeps.head().room;
        let getDistinct=function (roomName1,roomName2) {
            let avoidRooms = BetterMove.getAvoidRoomsMap();
            const ops = {
                routeCallback(roomName) {
                    if(avoidRooms[roomName]) {    // 回避这个房间
                        return Infinity;
                    }
                    return 1;
                }};
            let dist = Game.map.getRoomLinearDistance(roomName1, roomName2, false)
            if(dist<2) dist = Game.map.findRoute(roomName1,roomName2,ops).length
            return dist;
        }
        let dist = getDistinct(creeps.head().room.name , flag.pos.roomName)

        // let hostiles = currRoom.find(FIND_HOSTILE_CREEPS);
        // if (hostiles.find(h => creeps.find(e => e.pos.getRangeTo(h) <= 5))) {
        //     return flag.memory.mode = "flee";
        // }

        if((dist)<=2){//&&flag._creeps.length>=3
            if(currRoom.my){
                let permitArea = WarCache.getPermitArea(currRoom.name,true);
                if(permitArea.get(creeps[0].pos.x,creeps[0].pos.y))
                    return flag.memory.mode = "line"
            }
        }else return flag.memory.mode = "line"
    },
    exec (flag){
        let creeps = flag._creeps;
        if(!creeps||!creeps.length)return;
        if(flag.memory.keepMode)return;
        if(pro.checkMoveMode(flag))return;
        if (!flag.memory.forceStructs) {
            flag.memory.mode="attack"
        }
    }
}


global.WarTeamControl = pro;

modules.war_damageCal:
/**
 Module: WarDamageCal
 Author: fangxm
 Date:   2020.02.04
 Usage:

 要计算tower该不该打一个creep或者creep该不该逃跑：
 let towerDamage = possibleTowerDamage(room, creep.pos);
 let break = wouldBreakDefend(creep.body, creep.pos, 你的用户名, towerDamage)
 if (break) {
     ...
 }

 这个模块是计算伤害的工具模块
 */

let pro = {
    /**
     * 计算点到tower的伤害
     * @param {number} dist 点到tower的距离
     */
    calTowerDamage(dist) {
        if (dist <= 5) return 600;
        else if (dist <= 20) return 600 - (dist - 5) * 30;
        else return 150;
    },

    /**
     * 计算在一个房间内一个点的tower伤害总值
     * @param {Room} room tower所在房间
     * @param {RoomPosition} pos 要计算伤害的点
     */
    possibleTowerDamage(room, pos) {
        return _.sum(room.towers, tower => {
            if (tower.store.energy < 10) return 0;
            let ratio = 1;
            if (tower.effects && tower.effects.length) tower.effects.forEach(effect => {
                if (effect.effect == PWR_OPERATE_TOWER) ratio = POWER_INFO[effect.effect].effect[effect.level];
            });
            return calTowerDamage(tower.pos.getRangeTo(pos)) * ratio;
        });
    },

    /**
     * 计算一个creep在某个位置可能受到的伤害
     * @param {BodyPartDefinition[]} body 该creep的body
     * @param {RoomPosition} pos 要计算伤害的位置
     * @param {string} username 用户名
     * @param {boolean} heal 是否计算治疗值，默认为true
     * @param {number} towerDamage tower在该位置的伤害，默认为0
     * @param {boolean} risk 计不计算威胁值（攻击范围之外的creep），默认为false
     */
    possibleDamage(body, pos, username, heal = true, towerDamage = 0, risk = false) {
        let attackers = pos.findInRange(FIND_CREEPS, risk ? 50 : 3,
            { filter: creep => creep.owner.username != username && (creep.bodyCounts[ATTACK] || creep.bodyCounts[RANGED_ATTACK]) });

        let possibleDamage = _.sum(attackers, attacker => possibleCreepDamage(attacker.body, pos.getRangeTo(attacker), risk)) + (towerDamage || 0);
        possibleDamage = hitsOnTough(body, possibleDamage);
        let possibleHeal = 0;
        if (heal) {
            let healers = pos.findInRange(FIND_CREEPS, 3, { filter: creep => creep.owner.username == username && creep.bodyCounts[HEAL] });
            possibleHeal = possibleHealHits(pos, healers);
        }
        return possibleDamage - possibleHeal;
    },

    /**
     * 计算一个creep在某个位置是否会被破防
     * @param {BodyPartDefinition[]} body 该creep的body
     * @param {RoomPosition} pos 要计算的位置
     * @param {string} username 用户名
     * @param {number} towerDamage tower在该位置的伤害，默认为0
     * @param {boolean} risk 计不计算威胁值（攻击范围之外的creep），默认为false
     */
    wouldBreakDefend(body, pos, username, towerDamage = 0, risk = false) {
        return possibleDamage(body, pos, username, true, towerDamage, risk) > 0;
    }
}

