            .concat(ManagerCreeps.calcBodyPart({ [ATTACK]: 25 ,[TOUGH]: 6,[MOVE]: 10}))
    },
    getBoostWork (){
        return ManagerCreeps.calcBodyPart({ [WORK]: 5 ,[TOUGH]: 6, })
            .concat(ManagerCreeps.calcBodyPart({ [WORK]: 29,[MOVE]: 10}))
    },
    getBoostRangeAttack (){
